mapper.select:
select  from content.content_item c
join source.source_entity s on s.id = c.source_entity_id

    c.admission_status = #{status}
    and c.fact_status = #{factStatus}
    and
        (c.original_title ilike '%' || #{query} || '%' or c.title_zh ilike '%' || #{query} || '%' or s.name ilike '%' || #{query} || '%')


order by case when c.admission_status in ('PENDING', 'REVIEW_REQUIRED') then 0 else 1 end,
         c.updated_at desc, c.id desc limit #{limit}

select id, content_item_id, event_cluster_id, ticket_type, status, priority, reason,
       contact_email, resolution, submitted_by, assigned_to, resolved_by, created_at, resolved_at
from governance.content_ticket
where status = #{status}
order by case priority when 'URGENT' then 0 when 'HIGH' then 1 when 'NORMAL' then 2 else 3 end,
         created_at, id limit #{limit}

select id, content_item_id, event_cluster_id, ticket_type, status, priority, reason,
       contact_email, resolution, submitted_by, assigned_to, resolved_by, created_at, resolved_at
from governance.content_ticket where id = #{id}
